import { fraction } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, PracticeItem } from '../../features/unit-v2/types.ts'
import { same, say } from '../batx1-zientziak-funtzioak/text.ts'

/* ==========================================================================
   Funtzioen adierazpena · Batxilergoa 2 · Zientziak — diagnostic, guided
   practice, exercise bank and challenges, with the scope of unit 10 of
   Santillana 2.º Bachillerato Ciencias and unit 10 of Anaya Matemáticas
   II (all the exercises and numbers are our own; «study and sketch» and
   «read f from the graph of f′» follow the style of the Basque EBAU).
   Every closed answer is a single number: where an asymptote is, a
   coefficient of an oblique asymptote, an abscissa of an extremum or an
   inflection, a period, how many asymptotes, corners or intercepts there
   are, or a parameter. The «sketch» exercises are open: their solution
   is the whole study.
   ========================================================================== */

const n = (value: number) => fraction(value)
const f = (numerator: number, denominator: number) => fraction(numerator, denominator)

/** «At which abscissa does f have its …?» */
const abscissa = (kind: 'max' | 'min' | 'inflection', fn: string) => ({
    max: say(`Zein abzisatan du $f(x)=${fn}$ funtzioak maximo erlatiboa?`, `¿En qué abscisa tiene $f(x)=${fn}$ su máximo relativo?`, `عند أي فاصلة تبلغ $f(x)=${fn}$ قيمتها العظمى المحلية؟`, `At which abscissa does $f(x)=${fn}$ have its local maximum?`),
    min: say(`Zein abzisatan du $f(x)=${fn}$ funtzioak minimo erlatiboa?`, `¿En qué abscisa tiene $f(x)=${fn}$ su mínimo relativo?`, `عند أي فاصلة تبلغ $f(x)=${fn}$ قيمتها الصغرى المحلية؟`, `At which abscissa does $f(x)=${fn}$ have its local minimum?`),
    inflection: say(`Zein abzisatan du $f(x)=${fn}$ funtzioak inflexio-puntua?`, `¿En qué abscisa tiene $f(x)=${fn}$ su punto de inflexión?`, `عند أي فاصلة تكون نقطة انعطاف $f(x)=${fn}$؟`, `At which abscissa does $f(x)=${fn}$ have its point of inflection?`)
})[kind]
const vertical = (fn: string) => say(`Zein abzisatan du $f(x)=${fn}$ funtzioak asintota bertikala?`, `¿En qué abscisa tiene $f(x)=${fn}$ su asíntota vertical?`, `عند أي فاصلة يقع المقارب الرأسي للدالة $f(x)=${fn}$؟`, `At which abscissa does $f(x)=${fn}$ have its vertical asymptote?`)
const horizontal = (fn: string) => say(`$f(x)=${fn}$ funtzioaren asintota horizontala $y=k$ da. Zenbat da $k$?`, `La asíntota horizontal de $f(x)=${fn}$ es $y=k$. ¿Cuánto vale $k$?`, `المقارب الأفقي للدالة $f(x)=${fn}$ هو $y=k$. كم تساوي $k$؟`, `The horizontal asymptote of $f(x)=${fn}$ is $y=k$. What is $k$?`)
const oblique = (fn: string, letter: string) => say(`$f(x)=${fn}$ funtzioaren asintota zeiharra $y=mx+n$ da. Zenbat da $${letter}$?`, `La asíntota oblicua de $f(x)=${fn}$ es $y=mx+n$. ¿Cuánto vale $${letter}$?`, `المقارب المائل للدالة $f(x)=${fn}$ هو $y=mx+n$. كم تساوي $${letter}$؟`, `The oblique asymptote of $f(x)=${fn}$ is $y=mx+n$. What is $${letter}$?`)
const rightOblique = (fn: string) => say(`$f(x)=${fn}$ funtzioaren eskuineko asintota zeiharra $y=x+n$ da. Zenbat da $n$?`, `La asíntota oblicua de $f(x)=${fn}$ por la derecha es $y=x+n$. ¿Cuánto vale $n$?`, `المقارب المائل للدالة $f(x)=${fn}$ من اليمين هو $y=x+n$. كم تساوي $n$؟`, `On the right, the oblique asymptote of $f(x)=${fn}$ is $y=x+n$. What is $n$?`)
const period = (fn: string) => say(`$f(x)=${fn}$ funtzioaren periodoa $k\\pi$ da. Zenbat da $k$?`, `El periodo de $f(x)=${fn}$ es $k\\pi$. ¿Cuánto vale $k$?`, `دور الدالة $f(x)=${fn}$ هو $k\\pi$. كم تساوي $k$؟`, `The period of $f(x)=${fn}$ is $k\\pi$. What is $k$?`)
const corners = (fn: string) => say(`Zenbat punta ditu $y=${fn}$ funtzioaren grafikoak?`, `¿Cuántos picos tiene la gráfica de $y=${fn}$?`, `كم زاوية في رسم $y=${fn}$؟`, `How many corners does the graph of $y=${fn}$ have?`)
const rightEdge = (fn: string) => say(`Non amaitzen da eskuinetik $f(x)=${fn}$ funtzioaren izate-eremua?`, `¿Dónde termina por la derecha el dominio de $f(x)=${fn}$?`, `أين ينتهي مجال $f(x)=${fn}$ من اليمين؟`, `Where does the domain of $f(x)=${fn}$ end on the right?`)
const sketch = (fn: string) => say(`Irudikatu $f(x)=${fn}$.`, `Representa $f(x)=${fn}$.`, `ارسم $f(x)=${fn}$.`, `Sketch $f(x)=${fn}$.`)
/** «The graph of f′ is y = …. At which abscissa does f have …?» */
const fromDerivative = (kind: 'max' | 'min' | 'inflection', fn: string) => ({
    max: say(`$f'$ deribatuaren grafikoa $y=${fn}$ da. Zein abzisatan du $f$ funtzioak maximo bat?`, `La gráfica de $f'$ es $y=${fn}$. ¿En qué abscisa tiene $f$ un máximo?`, `رسم $f'$ هو $y=${fn}$. عند أي فاصلة تكون لـ $f$ قيمة عظمى؟`, `The graph of $f'$ is $y=${fn}$. At which abscissa does $f$ have a maximum?`),
    min: say(`$f'$ deribatuaren grafikoa $y=${fn}$ da. Zein abzisatan du $f$ funtzioak minimo bat?`, `La gráfica de $f'$ es $y=${fn}$. ¿En qué abscisa tiene $f$ un mínimo?`, `رسم $f'$ هو $y=${fn}$. عند أي فاصلة تكون لـ $f$ قيمة صغرى؟`, `The graph of $f'$ is $y=${fn}$. At which abscissa does $f$ have a minimum?`),
    inflection: say(`$f'$ deribatuaren grafikoa $y=${fn}$ da. Zein abzisatan du $f$ funtzioak inflexio-puntu bat?`, `La gráfica de $f'$ es $y=${fn}$. ¿En qué abscisa tiene $f$ un punto de inflexión?`, `رسم $f'$ هو $y=${fn}$. عند أي فاصلة تكون لـ $f$ نقطة انعطاف؟`, `The graph of $f'$ is $y=${fn}$. At which abscissa does $f$ have a point of inflection?`)
})[kind]
/** A function that is continuous, or differentiable, with its parameter asked for */
const piecewise = (cases: string, kind: 'continuous' | 'differentiable', letter: string) => kind === 'continuous'
    ? say(`$f(x)=\\begin{cases}${cases}\\end{cases}$ jarraitua da. Zenbat da $${letter}$?`, `$f(x)=\\begin{cases}${cases}\\end{cases}$ es continua. ¿Cuánto vale $${letter}$?`, `$f(x)=\\begin{cases}${cases}\\end{cases}$ متصلة. كم تساوي $${letter}$؟`, `$f(x)=\\begin{cases}${cases}\\end{cases}$ is continuous. What is $${letter}$?`)
    : say(`$f(x)=\\begin{cases}${cases}\\end{cases}$ deribagarria da. Zenbat da $${letter}$?`, `$f(x)=\\begin{cases}${cases}\\end{cases}$ es derivable. ¿Cuánto vale $${letter}$?`, `$f(x)=\\begin{cases}${cases}\\end{cases}$ قابلة للاشتقاق. كم تساوي $${letter}$؟`, `$f(x)=\\begin{cases}${cases}\\end{cases}$ is differentiable. What is $${letter}$?`)

